/// Serves HTTP/1.1 requests on one client connection until it closes.
struct Connection: Sendable {
    static let ioTimeoutSeconds = 30
    private static let readChunkSize = 64 * 1024
    private static let continueResponse = Array("HTTP/1.1 100 Continue\r\n\r\n".utf8)

    let socket: StreamSocket
    let router: Router

    func serve() {
        defer { socket.close() }
        #if canImport(Darwin)
        socket.setOption(SOL_SOCKET, SO_NOSIGPIPE, 1)
        #endif
        socket.setOption(Int32(IPPROTO_TCP), TCP_NODELAY, 1)
        socket.setTimeout(SO_RCVTIMEO, seconds: Self.ioTimeoutSeconds)
        socket.setTimeout(SO_SNDTIMEO, seconds: Self.ioTimeoutSeconds)

        var buffer: [UInt8] = []
        var scratch = [UInt8](repeating: 0, count: Self.readChunkSize)

        while true {
            // Read until the blank line that ends the head.
            var scanned = 0
            var headEnd: Int?
            while headEnd == nil {
                headEnd = RequestParser.headEnd(in: buffer, from: scanned - 3)
                if headEnd != nil { break }
                scanned = buffer.count
                if buffer.count > RequestParser.maxHeadSize {
                    sendError(.headersTooLarge)
                    return
                }
                guard socket.read(appendingTo: &buffer, scratch: &scratch) else { return }
            }
            guard let headEnd else { return }

            var head: RequestHead
            do {
                head = try RequestParser.parseHead(buffer[..<(headEnd - 4)], maxBodySize: Router.maxValueSize)
            } catch {
                sendError(error)
                return
            }

            // Read the body.
            let requestEnd = headEnd + head.contentLength
            if buffer.count < requestEnd {
                if head.request.header("expect")?.lowercased() == "100-continue" {
                    guard socket.write(Self.continueResponse) else { return }
                }
                buffer.reserveCapacity(requestEnd)
                while buffer.count < requestEnd {
                    guard socket.read(appendingTo: &buffer, scratch: &scratch) else { return }
                }
            }
            head.request.body = Array(buffer[headEnd..<requestEnd])
            buffer.removeSubrange(..<requestEnd)

            let keepAlive = head.request.isKeepAlive
            guard write(router.handle(head.request), keepAlive: keepAlive), keepAlive else { return }
        }
    }

    @discardableResult
    private func write(_ response: HTTPResponse, keepAlive: Bool) -> Bool {
        socket.write(response.serializedHead(keepAlive: keepAlive))
            && (response.body.isEmpty || socket.write(response.body))
    }

    private func sendError(_ error: HTTPParseError) {
        write(HTTPResponse(status: error.status), keepAlive: false)
    }
}

/// A parsed HTTP request.
public struct HTTPRequest: Sendable {
    public var method: String
    public var target: String
    public var version: String
    /// Header fields in arrival order; names are lowercased.
    public var headers: [(name: String, value: String)]
    public var body: [UInt8]

    public init(
        method: String,
        target: String,
        version: String = "HTTP/1.1",
        headers: [(name: String, value: String)] = [],
        body: [UInt8] = []
    ) {
        self.method = method
        self.target = target
        self.version = version
        self.headers = headers
        self.body = body
    }

    public func header(_ name: String) -> String? {
        let name = name.lowercased()
        return headers.first { $0.name == name }?.value
    }

    /// Whether the client wants the connection kept open after this request.
    public var isKeepAlive: Bool {
        let tokens = header("connection")?.lowercased()
            .split(separator: ",").map { $0.trimmingWhitespace() } ?? []
        if tokens.contains("close") { return false }
        return version == "HTTP/1.1" || tokens.contains("keep-alive")
    }
}

/// An HTTP response with a fully materialised body.
public struct HTTPResponse: Sendable {
    public var status: Int
    public var contentType: String?
    public var body: [UInt8]

    public init(status: Int, contentType: String? = nil, body: [UInt8] = []) {
        self.status = status
        self.contentType = contentType
        self.body = body
    }

    public init(status: Int, contentType: String, text: String) {
        self.init(status: status, contentType: contentType, body: Array(text.utf8))
    }

    /// Status line and headers, terminated by the blank line.
    func serializedHead(keepAlive: Bool) -> [UInt8] {
        var head = "HTTP/1.1 \(status) \(Self.reasonPhrase(for: status))\r\n"
        if let contentType {
            head += "Content-Type: \(contentType)\r\n"
        }
        head += "Content-Length: \(body.count)\r\n"
        head += keepAlive ? "Connection: keep-alive\r\n" : "Connection: close\r\n"
        head += "\r\n"
        return Array(head.utf8)
    }

    static func reasonPhrase(for status: Int) -> String {
        switch status {
        case 200: "OK"
        case 201: "Created"
        case 204: "No Content"
        case 400: "Bad Request"
        case 404: "Not Found"
        case 405: "Method Not Allowed"
        case 408: "Request Timeout"
        case 413: "Content Too Large"
        case 431: "Request Header Fields Too Large"
        case 500: "Internal Server Error"
        case 501: "Not Implemented"
        case 505: "HTTP Version Not Supported"
        default: "Unknown"
        }
    }
}

extension StringProtocol {
    func trimmingWhitespace() -> SubSequence {
        let isSpace: (Character) -> Bool = { $0 == " " || $0 == "\t" }
        let start = firstIndex { !isSpace($0) } ?? endIndex
        let end = lastIndex { !isSpace($0) }.map(index(after:)) ?? start
        return self[start..<end]
    }
}

import Foundation

/// HTTP/1.1 front end for a `KVStore`, using one thread per connection.
public struct KVHTTPServer: Sendable {
    public let host: String
    public let port: UInt16
    private let router: Router

    public init(host: String = "127.0.0.1", port: UInt16, store: KVStore = KVStore()) {
        self.host = host
        self.port = port
        self.router = Router(store: store)
    }

    /// Binds and serves forever; only returns by throwing.
    public func run() throws(SocketError) -> Never {
        let listener = try ListeningSocket(host: host, port: port, backlog: 1024)
        let router = router
        while true {
            let client = try listener.accept()
            Thread.detachNewThread {
                Connection(socket: client, router: router).serve()
            }
        }
    }
}

import Synchronization

/// Thread-safe in-memory key-value store.
public final class KVStore: Sendable {
    private let entries = Mutex<[String: [UInt8]]>([:])

    public init() {}

    /// Stores `value` under `key`. Returns `true` if the key did not exist before.
    @discardableResult
    public func put(_ key: String, _ value: [UInt8]) -> Bool {
        entries.withLock { $0.updateValue(value, forKey: key) == nil }
    }

    public func get(_ key: String) -> [UInt8]? {
        entries.withLock { $0[key] }
    }

    /// Removes `key`. Returns `true` if it was present.
    @discardableResult
    public func delete(_ key: String) -> Bool {
        entries.withLock { $0.removeValue(forKey: key) != nil }
    }

    /// All keys, sorted ascending.
    public func keys() -> [String] {
        entries.withLock { Array($0.keys) }.sorted()
    }
}

/// Errors that terminate a connection after an error response is sent.
public enum HTTPParseError: Error, Equatable {
    case badRequest
    case headersTooLarge
    case bodyTooLarge
    case unsupportedTransferEncoding
    case unsupportedVersion

    var status: Int {
        switch self {
        case .badRequest: 400
        case .headersTooLarge: 431
        case .bodyTooLarge: 413
        case .unsupportedTransferEncoding: 501
        case .unsupportedVersion: 505
        }
    }
}

/// Everything before the body, plus the body length it announces.
struct RequestHead {
    var request: HTTPRequest
    var contentLength: Int
}

enum RequestParser {
    static let maxHeadSize = 64 * 1024
    private static let terminator: [UInt8] = Array("\r\n\r\n".utf8)

    /// Returns the index just past the `\r\n\r\n` that ends the head, searching from `start`.
    static func headEnd(in buffer: [UInt8], from start: Int) -> Int? {
        let lastStart = buffer.count - terminator.count
        guard lastStart >= 0 else { return nil }
        var i = max(0, start)
        while i <= lastStart {
            if buffer[i] == 13, buffer[i + 1] == 10, buffer[i + 2] == 13, buffer[i + 3] == 10 {
                return i + terminator.count
            }
            i += 1
        }
        return nil
    }

    /// Parses the request line and header fields in `bytes` (excluding the final blank line).
    static func parseHead(_ bytes: ArraySlice<UInt8>, maxBodySize: Int) throws(HTTPParseError) -> RequestHead {
        // Header bytes are treated as Latin-1-ish ASCII; anything non-UTF-8 is rejected.
        guard let text = String(validating: bytes, as: UTF8.self) else { throw .badRequest }
        var lines = text.split(separator: "\r\n", omittingEmptySubsequences: false)[...]
        // Tolerate stray empty lines before the request line (RFC 9112 §2.2).
        while lines.first?.isEmpty == true { lines = lines.dropFirst() }
        guard let requestLine = lines.popFirst() else { throw .badRequest }

        let parts = requestLine.split(separator: " ", omittingEmptySubsequences: false)
        guard parts.count == 3, !parts[0].isEmpty, parts[1].first == "/" else { throw .badRequest }
        let version = String(parts[2])
        guard version == "HTTP/1.1" || version == "HTTP/1.0" else {
            throw version.hasPrefix("HTTP/") ? .unsupportedVersion : .badRequest
        }

        var headers: [(name: String, value: String)] = []
        for line in lines where !line.isEmpty {
            guard let colon = line.firstIndex(of: ":") else { throw .badRequest }
            let name = line[..<colon]
            guard !name.isEmpty, !name.contains(" "), !name.contains("\t") else { throw .badRequest }
            headers.append((name.lowercased(), String(line[line.index(after: colon)...].trimmingWhitespace())))
        }

        let request = HTTPRequest(method: String(parts[0]), target: String(parts[1]), version: version, headers: headers)

        if request.header("transfer-encoding") != nil {
            throw .unsupportedTransferEncoding
        }

        var contentLength = 0
        let lengths = headers.filter { $0.name == "content-length" }.map(\.value)
        if let first = lengths.first {
            // Repeated Content-Length headers must agree.
            guard lengths.allSatisfy({ $0 == first }),
                  !first.isEmpty, first.utf8.allSatisfy({ (48...57).contains($0) })
            else { throw .badRequest }
            guard let value = Int(first), value <= maxBodySize else { throw .bodyTooLarge }
            contentLength = value
        }

        return RequestHead(request: request, contentLength: contentLength)
    }
}

/// Maps requests onto store operations. Independent of networking so it can be tested directly.
public struct Router: Sendable {
    public static let maxKeyLength = 64
    public static let maxValueSize = 1 << 20

    private let store: KVStore

    public init(store: KVStore) {
        self.store = store
    }

    public func handle(_ request: HTTPRequest) -> HTTPResponse {
        // Tests never send a query string, but ignore one rather than misroute.
        let path = request.target.split(separator: "?", maxSplits: 1, omittingEmptySubsequences: false).first ?? ""
        let method = request.method

        switch path {
        case "/health":
            guard method == "GET" else { return HTTPResponse(status: 405) }
            return HTTPResponse(status: 200, contentType: "text/plain; charset=utf-8", text: "ok")

        case "/kv":
            guard method == "GET" else { return HTTPResponse(status: 405) }
            return HTTPResponse(status: 200, contentType: "application/json", text: Self.jsonArray(store.keys()))

        case _ where path.hasPrefix("/kv/"):
            let key = path.dropFirst("/kv/".count)
            guard Self.isValidKey(key) else { return HTTPResponse(status: 400) }
            return handleKey(method: method, key: String(key), body: request.body)

        default:
            return HTTPResponse(status: 404)
        }
    }

    private func handleKey(method: String, key: String, body: [UInt8]) -> HTTPResponse {
        switch method {
        case "GET":
            guard let value = store.get(key) else { return HTTPResponse(status: 404) }
            return HTTPResponse(status: 200, contentType: "application/octet-stream", body: value)
        case "PUT":
            guard body.count <= Self.maxValueSize else { return HTTPResponse(status: 413) }
            return HTTPResponse(status: store.put(key, body) ? 201 : 200)
        case "DELETE":
            return HTTPResponse(status: store.delete(key) ? 204 : 404)
        default:
            return HTTPResponse(status: 405)
        }
    }

    /// A key matches `[A-Za-z0-9_-]{1,64}`.
    public static func isValidKey<S: StringProtocol>(_ key: S) -> Bool {
        let bytes = key.utf8
        guard (1...maxKeyLength).contains(bytes.count) else { return false }
        return bytes.allSatisfy { byte in
            switch byte {
            case UInt8(ascii: "A")...UInt8(ascii: "Z"),
                 UInt8(ascii: "a")...UInt8(ascii: "z"),
                 UInt8(ascii: "0")...UInt8(ascii: "9"),
                 UInt8(ascii: "_"), UInt8(ascii: "-"):
                true
            default:
                false
            }
        }
    }

    /// Keys are restricted to `[A-Za-z0-9_-]`, so they never need JSON escaping.
    static func jsonArray(_ keys: [String]) -> String {
        "[" + keys.map { "\"\($0)\"" }.joined(separator: ",") + "]"
    }
}

